INSERT INTO `dc_email_templates` (`id`, `store_id`, `name`, `title`, `content`, `tokens`, `status`, `can_del`) VALUES
(1, 1, 'REGISTRATION_EMAIL', 'Thông tin tài khoản tại {SITENAME}', 's:305:\"Xin chào {FULLNAME},\r\n\r\nCảm ơn bạn đã đăng ký tài khoản tại {SITENAME}. Thông tin tài khoản của bạn như sau:\r\n\r\nUsername: {USERNAME}\r\nMật khẩu: {PASSWORD}\r\n\r\nVui lòng click vào link{URL} để tài khoản được kích hoạt tại {SITENAME}\r\n\r\nTrân trọng,\r\n{SITENAME}\";', 'SITENAME,FULLNAME,USERNAME,PASSWORD,URL', 1, 0),
(2, 1, 'ORDER_CONFIRMATION', 'Xác nhận đơn đặt hàng tại {SITENAME}', 's:601:\"Xin chào {ORDERCUSNAME},<br /><br />\r\n\r\nChúng tôi đã nhận được đơn đặt hàng của bạn.<br /><br />\r\n\r\nMã đơn hàng: {ORDERID} <br />\r\nTên miền: {DOMAIN}<br/><br/>\r\n\r\nBạn có thể theo dõi tình hình triển khai đơn hàng tại địa chỉ: <br />\r\n{ORDERURL}<br /><br />\r\n\r\nTrân trọng.<br />\r\n----------------------------------<br/>\r\nBaomat.Website<br/><br/>\r\nOffice: 1209 Hiep Nhat, Ward 4, Tan Binh District, HCMC, Vietnam<br/>\r\n\r\nTel : (+84.8) 6268 0624 (102)  Fax: (+84.8) 6268 0615<br/>\r\n\r\nEmai : support@baomat.website Website: http://www.baomat.website<br/>\";', 'ORDERCUSNAME,ORDERID,ORDERPASSWORD,ORDERURL,SITENAME,DOMAIN', 1, 0),
(4, 1, 'ORDER_STATUS_CHANGE', 'Thay đổi thông tin đơn hàng tại {SITENAME}', 's:317:\"Xin chào {ORDERCUSNAME},\n\nTrạng thái đơn hàng {ORDERID} của bạn đã thay đổi, chi tiết như sau:\n\nTrạng thái cũ: {OLDSTATUS}\nTrạng thái mới: {STATUS}\n\nBạn có thể theo dõi trạng thái đơn hàng bằng cách nhấp vào liên kết sau: {ORDERURL}\n\nTrân trọng\n{SITENAME}\";', 'ORDERCUSNAME, ORDERID, ORDERDATE, OLDSTATUS, STATUS, SITENAME', 1, 0),
(6, 1, 'CONTACT_EMAIL', 'Thông tin liên hệ tại {SITENAME}', 's:302:\"Xin chào,\r\nBạn nhận được một email liên hệ từ {SITENAME}.\r\nThông tin liên hệ như sau: \r\nHọ tên: {FULLNAME}\r\nĐịa chỉ:{ADDRESS} \r\nEmail: {EMAIL}\r\nĐiện thoại: {TEL}\r\nNội dung: {CONTENT}\r\nVui lòng nhanh chóng liên hệ với khách hàng.\r\nTrân trọng.\r\n{SITENAME}.\";', 'SITENAME,FULLNAME,ADDRESS,EMAIL,TEL,CONTENT', 1, 0),
(7, 1, 'RESERVATION_EMAIL', 'Thông tin đặt phòng tại {SITENAME}', 's:857:\"Xin chào {FULLNAME}<br>\r\nThông tin đặt phòng của bạn đã được gửi đi thành công.<br>\r\nThông tin đặt phòng như sau:<br>\r\n<b>Tên cá nhân, tổ chức: </b>{FULLNAME}<br>\r\n<b>Địa chỉ: </b>{ADDRESS}<br>\r\n<b>Số điện thoại: </b>{TEL}<br>\r\n<b>Số điện thoại di động:</b> {CELL}<br>\r\n<b>Ngày đến:</b>{DATE_ARRIVE}<br>\r\n<b>Ngày đi:</b> {DATE_LEAVE}<br>\r\n<b>Số tiền cần thanh toán:</b> {MONEY} VNĐ<br>\r\nBạn hãy nhấp link dưới đây để theo dỏi tình trạng đơn đặt phòng<br>\r\nLink: {LINK}<br>\r\nCảm ơn bạn đã sử dụng dịch vụ của chúng tôi.<br>\r\n<b>{SITENAME}</b><br>\r\n<b>Địa chỉ:</b> A1-12 Khu Biệt Thự Sài Gòn Pearl, 92 Nguyễn Hữu Cảnh, P.22,Quận Bình Thạnh, TP HCM<br>\r\n<b>Điện thoại:</b> (+84.8) 3830 1234 <b>Fax:</b> (+84.8) 3830 1234\";', 'SITENAME,FULLNAME,FULLNAME,ADDRESS,TEL,CELL,DATE_ARRIVE,DATE_LEAVE,MONEY,LINK,SITENAME', 0, 0),
(8, 1, 'RESERVATION_EMAIL_EN', 'Infomation Reservation from {SITENAME}', 's:627:\"Hi {FULLNAME}<br>\r\nInfomation your reservation has been sent successfully.<br>\r\nContent:<br>\r\n<b>Name of individual or organization: </b>{FULLNAME}<br>\r\n<b>Address: </b>{ADDRESS}<br>\r\n<b>Telephone: </b>{TEL}<br>\r\n<b>Cell:</b> {CELL}<br>\r\n<b>Date arrive:</b>{DATE_ARRIVE}<br>\r\n<b>Date leave:</b> {DATE_LEAVE}<br>\r\n<b>Total money:</b> {MONEY} VNĐ<br>\r\nClick link below to track the status reservation<br>\r\nLink {LINK}<br>\r\nThanks .<br>\r\n<b>{SITENAME}</b><br>\r\n<b>Address:</b>A1-12 Park Villas Sai Gon Pearl, 92 Nguyen Huu Canh, P.22, Binh Thanh District, HCM City<br>\r\n<b>Tel:</b> (+84.8) 3830 1234 <b>Fax:</b> (+84.8) 3830 1234\";', 'SITENAME,FULLNAME,FULLNAME,ADDRESS,TEL,CELL,DATE_ARRIVE,DATE_LEAVE,MONEY,LINK,SITENAME', 0, 0),
(9, 1, 'ORDER_NEW_NOTE', 'Thông tin xử lý đơn hàng tại {SITENAME}', 's:436:\"Xin chào {NAME},\r\n<br/><br/>\r\nĐơn hàng: {ORDERID}<br/>\r\nTên miền: {DOMAIN}<br/>\r\nLink đơn hàng: {LINK}<br/><br/>\r\n{NOTE}\r\n<br/><br/>\r\nTrân trọng.<br/>\r\n----------------------------------<br/>\r\nBaomat.Website<br/><br/>\r\n\r\n \r\nOffice: 1209 Hiep Nhat, Ward 4, Tan Binh District, HCMC, Vietnam<br/>\r\n\r\nTel : (+84.8) 6268 0624 (102)  Fax: (+84.8) 6268 0615</br>\r\n\r\nEmai : support@baomat.website Website: http://www.baomat.website\";', 'NAME,NOTE,LINK,ORDERID,DOMAIN,SITENAME', 1, 1);
INSERT INTO `dc_estores` (`id`, `owner_id`, `area_id`, `cat_id`, `subdomain`, `domain`, `name`, `en_name`, `keywords`, `description`, `company`, `address`, `tel`, `cell`, `email`, `created`, `expire`, `properties`, `type`, `status`) VALUES
(1, 26, 1, 1, 'estore', 'mpx.vn', 'CÔNG TY TNHH MELODY PRODUCTIONWORX', 'mpx.vn', 'CÔNG TY TNHH MELODY PRODUCTIONWORX', 'Melody Productionworx chuyên thiết kế, thi công và lắp đặt sân khấu, gian hàng triển lãm, activation, hộp đèn quảng cáo và giải pháp cơ khí chuyển động cho sự kiện, live concert trên toàn quốc.', '', '', '0966797494', '', 'info@mpx.vn', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'a:91:{i:0;s:0:\"\";s:10:\"price_room\";s:0:\"\";s:18:\"domain_template_id\";s:2:\"13\";s:28:\"check_duplicate_product_name\";s:0:\"\";s:8:\"currency\";s:3:\"VND\";s:10:\"admin_logo\";s:31:\"/upload/images/logo-favicon.png\";s:10:\"store_logo\";s:45:\"/upload/images/LOGO_MELODY_PRODUCTIONWORX.png\";s:13:\"custom_vercss\";s:3:\"6.0\";s:12:\"custom_intro\";s:583:\"Thanh An là chuỗi cửa hàng chuyên phân phối các sản phẩm lốp xe ô tô, ắc quy, đồ chơi, nội thất ô tô. Các sản phẩm tại Thanh An đều 100% chính hãng, bảo hành đầy đủ. Bên cạnh đó, Thanh An còn cung cấp các dịch vụ liên quan như rửa xe thay dầu, cứu hộ ắc quy, căn chỉnh lốp, cân bằng động,...Với phương châm “Uy tín, chất lượng và giá tốt nhất cho người tiêu dùng”, Thanh An vinh hạnh trở thành người bạn tin cậy luôn đồng hành chăm sóc cho xế yêu.\";s:14:\"custom_linkmap\";s:311:\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.123456789!2d106.6642711!3d10.692069!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31752f97b400fd13%3A0x292925fdcdf0f6c0!2zQjgvMjU1RSwg4bqlcCAyLCBQaG9uZyBQaMO6LCBCw6luaCBDaMOhbmgsIEjhu5MgQ2jDrSBNaW5o!5e0!3m2!1svi!2svn!4v1714000000000!5m2!1svi!2svn\";s:11:\"custom_open\";s:36:\"Thứ 2 - Chủ nhật 08:00 - 18:00\";s:9:\"custom_yb\";s:1:\"1\";s:9:\"custom_im\";s:1:\"2\";s:9:\"custom_gg\";s:1:\"3\";s:9:\"custom_tw\";s:1:\"4\";s:14:\"custom_fanpage\";s:1:\"5\";s:13:\"custom_linkfb\";s:1:\"6\";s:15:\"custom_chinhanh\";s:322:\"<ul class=\"footer__list\">\r\n	<li class=\"footer__list__item\">Chi nh&aacute;nh 1: 123 Nguyễn Thị Thập, Phường T&acirc;n Ph&uacute;, Quận 7, Tp. Hồ Ch&iacute; Minh</li>\r\n	<li class=\"footer__list__item\">Chi nh&aacute;nh 2: 73 L&yacute; Th&aacute;i Tổ, Phường 1, Quận 10, Tp. Hồ Ch&iacute; Minh</li>\r\n</ul>\";s:9:\"custom_bh\";s:9305:\"<p dir=\"ltr\" style=\"text-align:justify\"><strong><span style=\"background-color:transparent; color:rgb(59, 30, 0); font-family:inter,sans-serif; font-size:13.5pt\">Điều kiện bảo h&agrave;nh miễn ph&iacute;</span></strong></p>\r\n\r\n<ol>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm c&ograve;n trong thời hạn bảo h&agrave;nh v&agrave; c&oacute; đăng k&yacute; bảo h&agrave;nh.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm bị hư do lỗi kỹ thuật của nh&agrave; sản xuất.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Phiếu bảo h&agrave;nh phải được xuất tr&igrave;nh khi c&oacute; y&ecirc;u cầu bảo h&agrave;nh miễn ph&iacute;.&nbsp;</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Phiếu bảo h&agrave;nh phải c&ograve;n nguy&ecirc;n vẹn, phải thể hiện r&otilde; t&ecirc;n kh&aacute;ch h&agrave;ng v&agrave; ng&agrave;y mua, kh&ocirc;ng chắp nối, kh&ocirc;ng bị tẩy x&oacute;a.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Trong thời hạn bảo h&agrave;nh khi sản phẩm c&oacute; trục trặc hay sự cố, kh&aacute;ch h&agrave;ng vui l&ograve;ng li&ecirc;n lạc với trạm bảo h&agrave;nh gần nhất để được tư vấn bảo h&agrave;nh miễn ph&iacute; tại nh&agrave;.</span></p>\r\n	</li>\r\n</ol>\r\n\r\n<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; color:rgb(59, 30, 0); font-family:inter,sans-serif; font-size:13.5pt\"><strong>Lưu &yacute;:</strong> <em>Trong trường hợp cần chuyển sản phẩm đến trạm bảo h&agrave;nh để sửa chữa th&igrave; kỹ thuật của trạm bảo h&agrave;nh sẽ l&agrave; người quyết định v&agrave; trong trường hợp n&agrave;y kh&aacute;ch h&agrave;ng phải trả chi ph&iacute; vận chuyển sản phẩm từ nh&agrave; đến trạm bảo h&agrave;nh v&agrave; ngược lại.</em></span></p>\r\n\r\n<p dir=\"ltr\" style=\"text-align:justify\"><strong><span style=\"background-color:transparent; color:rgb(59, 30, 0); font-family:inter,sans-serif; font-size:13.5pt\">Kh&ocirc;ng được bảo h&agrave;nh trong c&aacute;c trường hợp</span></strong></p>\r\n\r\n<ol>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm đ&atilde; hết hạn bảo h&agrave;nh.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Kh&ocirc;ng c&oacute; phiếu bảo h&agrave;nh hay chứng từ h&oacute;a đơn li&ecirc;n quan đến sản phẩm.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm bị hư hỏng do thi&ecirc;n tai, lũ lụt, s&eacute;t đ&aacute;nh, hỏa hoạn hay do vận chuyển l&agrave;m nứt, m&oacute;p, bể, trầy xước.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm hư hỏng do sử dụng kh&ocirc;ng đ&uacute;ng theo hướng dẫn, do lắp đặt kh&ocirc;ng đ&uacute;ng kỹ thuật, do nguồn điện kh&ocirc;ng đ&uacute;ng, kh&ocirc;ng ổn định về điện thế hoặc tần số.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm bị rỉ s&eacute;t, ố bẩn do ăn m&ograve;n hay do chất lỏng đổ v&agrave;o</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">Sản phẩm c&oacute; dấu hiệu đ&atilde; th&aacute;o lắp, sửa chữa thay thế linh kiện ở những nơi kh&aacute;c ngo&agrave;i c&aacute;c trạm bảo h&agrave;nh.</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">&nbsp;C&aacute;c phụ kiện k&egrave;m theo sản phẩm kh&ocirc;ng phải l&agrave; linh kiện bảo h&agrave;nh. V&iacute; dụ: tặng phẩm khuyến m&atilde;i, một số phụ kiện k&egrave;m theo kh&aacute;c như bộ lọc sơ vải, lưới khử m&ugrave;i, pin v.v&hellip;</span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\" style=\"list-style-type: decimal; font-size: 13.5pt; font-family: Inter, sans-serif; color: rgb(59, 30, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space: pre;\">\r\n	<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"background-color:transparent; font-size:13.5pt\">C&aacute;c trường hợp y&ecirc;u cầu về vệ sinh sản phẩm, bảo tr&igrave; sản phẩm kh&ocirc;ng nằm trong c&aacute;c hạng mục bảo h&agrave;nh.</span></p>\r\n	</li>\r\n</ol>\";s:14:\"custom_cam_ket\";s:1850:\"<div class=\"container\">\r\n<h2>Cam kết từ Thanh An Autocare</h2>\r\n\r\n<div class=\"commitment__description description\">ThanhAn Autocare&nbsp;chuy&ecirc;n cung cấp c&aacute;c sản phẩm, phụ kiện &ocirc; t&ocirc; ch&iacute;nh h&atilde;ng, được nhập khẩu trực tiếp từ c&aacute;c thương hiệu nổi tiếng tr&ecirc;n to&agrave;n thế giới</div>\r\n\r\n<div class=\"grid\">\r\n<div class=\"row\">\r\n<div class=\"col l-3 m-6 c-6\">\r\n<div class=\"commitment__card\"><img alt=\"BẢO HÀNH CHÍNH HÃNG\" class=\"commitment__img\" src=\"/templates/oto/img/commitment1.svg\" />\r\n<h4>BẢO H&Agrave;NH CH&Iacute;NH H&Atilde;NG</h4>\r\n\r\n<p>Ch&uacute;ng t&ocirc;i bảo h&agrave;nh ch&iacute;nh h&atilde;ng &aacute;p dụng cho tất cả c&aacute;c sản phẩm.</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col l-3 m-6 c-6\">\r\n<div class=\"commitment__card\"><img alt=\"KĨ THUẬT CHUYÊN NGHIỆP\" class=\"commitment__img\" src=\"/templates/oto/img/commitment2.svg\" />\r\n<h4>KĨ THUẬT CHUY&Ecirc;N NGHIỆP</h4>\r\n\r\n<p>Ch&uacute;ng t&ocirc;i kh&ocirc;ng ngừng cải tiến kĩ thuật để đem lại dịch vụ tốt nhất cho bạn</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col l-3 m-6 c-6\">\r\n<div class=\"commitment__card\"><img alt=\"PHỤC VỤ TẬN TÂM\" class=\"commitment__img\" src=\"/templates/oto/img/commitment3.svg\" />\r\n<h4>PHỤC VỤ TẬN T&Acirc;M</h4>\r\n\r\n<p>Ch&uacute;ng t&ocirc;i nỗ lực kh&ocirc;ng ngừng để cải tiến dịch vụ.</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col l-3 m-6 c-6\">\r\n<div class=\"commitment__card\"><img alt=\"HÀNG HÓA PHONG PHÚ ĐA DẠNG\" class=\"commitment__img\" src=\"/templates/oto/img/commitment4.svg\" />\r\n<h4>H&Agrave;NG H&Oacute;A PHONG PH&Uacute; ĐA DẠNG</h4>\r\n\r\n<p>Ch&uacute;ng t&ocirc;i phục vụ tất cả những g&igrave; cần thiết cho chiếc xe của bạn.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\";s:17:\"custom_view_price\";s:1:\"2\";s:25:\"custom_service_commitment\";s:1229:\"<ul dir=\"ltr\">\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">Sản phẩm ch&iacute;nh h&atilde;ng 100%</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">100% b&igrave;nh ắc quy mới</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">C&aacute;c sản phẩm ắc quy đều c&oacute; đầy đủ phiếu bảo h&agrave;nh ch&iacute;nh h&atilde;ng</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">Đổi trả mới 100% nếu lỗi của nh&agrave; sản xuất</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">Gi&aacute; cả cạnh tranh</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">Lắp đặt miễn ph&iacute; tại cửa h&agrave;ng</span></span></li>\r\n	<li><span style=\"font-size:18px\"><span style=\"color:rgb(59, 30, 0); font-family:inter,sans-serif\">Dịch vụ lắp đặt tận nơi</span></span></li>\r\n</ul>\";s:15:\"custom_linkzalo\";s:1:\"9\";s:16:\"custom_linkggmap\";s:196:\"https://www.google.com/maps/place/ThanhAn+AutoCare/@10.737913,106.720711,15z/data=!4m6!3m5!1s0x31752f87211f819d:0xad2a390f3b77fca!8m2!3d10.737913!4d106.7207105!16s%2Fg%2F11gb3rjvxc?hl=en&entry=ttu\";s:17:\"custom_meta_title\";s:109:\"Melody Productionworx | Giải Pháp Sân Khấu, Triển Lãm Và Cơ Khí Chuyển Động Chuyên Nghiệp\";s:14:\"custom_meta_h1\";s:35:\"CÔNG TY TNHH MELODY PRODUCTIONWORX\";s:23:\"custom_meta_description\";s:238:\"Melody Productionworx chuyên thiết kế, thi công và lắp đặt sân khấu, gian hàng triển lãm, activation, hộp đèn quảng cáo và giải pháp cơ khí chuyển động cho sự kiện, live concert trên toàn quốc.\";s:19:\"custom_meta_keyword\";s:242:\"Melody Productionworx,MPX,sân khấu,triển lãm,thiết kế gian hàng triển lãm,thi công gian hàng triển lãm,activation,roadshow,hộp đèn quảng cáo,cơ khí chuyển động,live concert,stage motion,kết cấu sân khấu\";s:13:\"custom_tiktok\";s:1:\"7\";s:20:\"custom_name_file_img\";s:8:\"mpx-imgs\";s:13:\"custom_notifi\";s:1743:\"<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"font-size:12px\"><span style=\"color:#283373\"><strong><span style=\"font-family:arial,helvetica,sans-serif\"><img alt=\"laugh\" src=\"https://thanhanautocare.com/ckeditor/plugins/smiley/images/teeth_smile.png\" style=\"height:23px; width:23px\" title=\"laugh\" /><span style=\"font-size:14px\"><span style=\"background-color:transparent\">Th&ocirc;ng b&aacute;o: Khai xu&acirc;n c&ugrave;ng Thanh An Autocare</span></span></span></strong></span></span></p>\r\n\r\n<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"font-size:12px\"><span style=\"color:#283373\"><strong><span style=\"font-family:arial,helvetica,sans-serif\"><img alt=\"wink\" src=\"https://thanhanautocare.com/ckeditor/plugins/smiley/images/wink_smile.png\" style=\"height:23px; width:23px\" title=\"wink\" /></span></strong><span style=\"font-family:arial,helvetica,sans-serif\">Thanh An ch&iacute;nh thức<strong> khai xu&acirc;n v&agrave;o ng&agrave;y&nbsp;</strong></span></span><span style=\"color:rgb(40, 51, 115); font-family:arial,sans-serif\"><strong>05/02/2025 (M&ugrave;ng 8 Tết)</strong>. Rất h&acirc;n hạnh được phục vụ qu&yacute; kh&aacute;ch trở lại!</span></span></p>\r\n\r\n<p dir=\"ltr\" style=\"text-align:justify\"><span style=\"font-size:12px\"><span style=\"color:rgb(40, 51, 115)\"><span style=\"font-family:arial,helvetica,sans-serif\"><span style=\"background-color:transparent\"><img alt=\"heart\" src=\"https://thanhanautocare.com/ckeditor/plugins/smiley/images/heart.png\" style=\"height:23px; width:23px\" title=\"heart\" /></span></span></span><strong><span style=\"color:rgb(40, 51, 115); font-family:arial,sans-serif\">K&iacute;nh ch&uacute;c Qu&yacute; Kh&aacute;ch Năm mới An Khang - Thịnh Vượng!</span></strong></span></p>\";s:19:\"custom_onoff_notifi\";s:1:\"2\";s:10:\"custom_car\";s:72:\"Lốp  {namecar}: Thông số và Bảng giá mới nhất {datePresent}\";s:24:\"custom_text1h1carcompany\";s:30:\"Bảng giá lốp xe {namecar}\";s:24:\"custom_text2h1carcompany\";s:132:\"Sau khi nắm được các thông số lốp của {namecar}, bạn có thể tham khảo các sản phẩm sau để lắp cho xe:\";s:24:\"custom_text3h1carcompany\";s:35:\"Xe {namecar} sử dụng lốp size\";s:24:\"custom_text4h1carcompany\";s:68:\"Tổng hợp phụ kiện, phụ tùng, đồ chơi cho xe {namecar}\";s:27:\"custom_onoff_caraccessories\";s:1:\"2\";s:16:\"custom_onoff_car\";s:1:\"1\";s:16:\"custom_trademark\";s:72:\"Lốp  {nametra}: Thông số và Bảng giá mới nhất {datePresent}\";s:14:\"custom_text1h1\";s:55:\"Lốp {nametra} lắp được cho các xe ô tô nào?\";s:14:\"custom_text2h1\";s:64:\"Bảng giá lốp {nametra} chi tiết cập nhật mới nhất\";s:14:\"custom_text3h1\";s:73:\"Lốp {nametra} có giá bán trên thị trường từ {price} đồng.\";s:11:\"custom_luuy\";s:430:\"Giá lốp xe phụ thuộc vào nhiều yếu tố, bao gồm kích thước (size), dòng lốp, mã gai, xuất xứ và năm sản xuất. Để đảm bảo bạn chọn đúng sản phẩm với mức giá phù hợp, vui lòng kiểm tra kỹ thông tin chi tiết trước khi quyết định mua hàng. Cùng Thanh An chung tay nói không với lốp giả, lốp nhái, vì sự an toàn của bạn và cộng đồng!\";s:14:\"custom_text4h1\";s:49:\"Các thương hiệu lốp tương tự {nametra}\";s:14:\"custom_text5h1\";s:670:\"Thanh An cung cấp đa dạng các thương hiệu lốp xe hàng hàng đầu thế giới, đáp ứng mọi nhu cầu và ngân sách của bạn. Từ những cái tên quen thuộc như Goodyear, Bridgestone, Continental, Dunlop, Michelin, Yokohama, BFGoodrich, Kumho, Toyo, Pirelli, Hankook, Maxxis, Presa, Atlas, Deestone, Leao, Advenza, Milestar...tất cả đều đã có mặt tại hệ thống cửa hàng của chúng tôi. Khách hàng có thể thoải mái so sánh và lựa chọn sản phẩm phù hợp nhất với xe và phong cách lái của mình. Hãy đến Thanh An để trải nghiệm sự đa dạng và chất lượng vượt trội!\";s:16:\"onoff_trademake1\";s:1:\"1\";s:15:\"onoff_trademake\";s:1:\"1\";s:22:\"onoff_trademakesimilar\";s:1:\"1\";s:14:\"custom_address\";s:52:\"B8/255E, Ấp 2, Xã Bình Hưng, TP. Hồ Chí Minh\";s:23:\"custom_sales_commitment\";s:1369:\"<h2><a id=\"Cam kết bán hàng\" name=\"Cam kết bán hàng\">Cam kết b&aacute;n h&agrave;ng</a></h2>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\"><span style=\"font-family:arial,helvetica,sans-serif\">Kh&aacute;m ph&aacute; những sản phẩm {nametra} được ưa chuộng nhất tại Thanh An! Ch&uacute;ng t&ocirc;i tự h&agrave;o mang đến cho bạn trải nghiệm mua sắm đ&aacute;ng tin cậy với cam kết chất lượng tuyệt đối. Mọi sản phẩm đều l&agrave; h&agrave;ng ch&iacute;nh h&atilde;ng, k&egrave;m h&oacute;a đơn đầy đủ, đảm bảo sự an t&acirc;m cho bạn. </span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\"><span style=\"font-family:arial,helvetica,sans-serif\">Thanh An cam kết bồi thường gấp đ&ocirc;i (200%) gi&aacute; trị đơn h&agrave;ng nếu ph&aacute;t hiện h&agrave;ng giả, h&agrave;ng nh&aacute;i. Sản phẩm c&ograve;n được bảo h&agrave;nh điện tử với tem chống h&agrave;ng giả, gi&uacute;p bạn y&ecirc;n t&acirc;m sử dụng. Ch&uacute;ng t&ocirc;i hỗ trợ vận chuyển to&agrave;n quốc với mức ph&iacute; ưu đ&atilde;i. Đội ngũ tư vấn vi&ecirc;n lu&ocirc;n sẵn s&agrave;ng hỗ trợ 24/7 qua hotline 0906 662 441. H&atilde;y li&ecirc;n hệ ngay để được tư vấn!</span></span></p>\";s:11:\"custom_size\";s:66:\"Lốp {namesize} giá bao nhiêu? Lắp được cho các xe nào?\";s:18:\"custom_text1h1size\";s:32:\"Bảng giá lốp xe {namesize}.\";s:18:\"custom_text2h1size\";s:407:\"ThanhAn là đại lý phân phối chính hãng các sản phẩm ắc quy và lốp từ các thương hiệu lớn như Michelin, Bridgestone,... với chính sách bảo hành tuyệt đối. Giá lốp xe chỉ từ {gia_thap} đồng cho một quả lốp, được tặng kèm theo nhiều ưu đãi hấp dẫn. Dưới đây là bảng giá sản phẩm lốp size {namesize} do ThanhAn cung cấp:\";s:17:\"custom_onoff_size\";s:1:\"1\";s:18:\"custom_link_shopee\";s:1:\"8\";s:13:\"custom_lazada\";s:2:\"10\";s:20:\"custom_link_facebook\";s:46:\"https://www.facebook.com/melodyproductionworx/\";s:16:\"custom_link_zalo\";s:26:\"https://zalo.me/0966797494\";s:19:\"custom_phone_mobile\";s:10:\"0942710025\";s:20:\"custom_exchange_rate\";s:5:\"26500\";s:10:\"custom_vat\";s:4:\"0.08\";s:23:\"custom_year_established\";s:2:\"12\";s:18:\"custom_event_month\";s:3:\"20+\";s:25:\"custom_professional_staff\";s:4:\"200+\";s:19:\"custom_factory_area\";s:9:\"20,000m²\";s:10:\"custom_mst\";s:10:\"0312710206\";s:19:\"custom_link_twitter\";s:16:\"https://mpx.vn/#\";s:19:\"custom_link_youtube\";s:45:\"https://www.youtube.com/@MelodyProductionworx\";s:21:\"custom_link_instagram\";s:16:\"https://mpx.vn/#\";s:21:\"custom_default_avatar\";s:40:\"/templates/mpx/img/logo/logo-favicon.png\";s:20:\"custom_en_meta_title\";s:84:\"Melody Productionworx | Professional Stage, Exhibition & Motion Mechanical Solutions\";s:22:\"custom_en_meta_keyword\";s:211:\"Melody Productionworx, MPX, stage, exhibition, exhibition booth design, exhibition booth construction, activation, roadshow, advertising lightboxes, motion mechanics, live concert, stage motion, stage structures\";s:26:\"custom_en_meta_description\";s:219:\"Melody Productionworx specializes in the design, construction, and installation of stages, exhibition booths, activations, advertising lightboxes, and motion mechanical solutions for events and live concerts nationwide.\";s:17:\"custom_en_meta_h1\";s:35:\"CÔNG TY TNHH MELODY PRODUCTIONWORX\";s:21:\"custom_link_messenger\";s:54:\"https://www.facebook.com/profile.php?id=61551213373339\";s:17:\"custom_link_skype\";s:16:\"https://mpx.vn/#\";s:20:\"custom_link_telegram\";s:16:\"https://mpx.vn/#\";s:21:\"custom_en_description\";s:219:\"Melody Productionworx specializes in the design, fabrication, and installation of stages, exhibition booths, activations, advertising light boxes, and mechanical motion solutions for events and live concerts nationwide.\";s:20:\"custom_zh_meta_title\";s:72:\"Melody Productionworx | 专业舞台、展览及动态机械解决方案\";s:22:\"custom_zh_meta_keyword\";s:171:\"Melody Productionworx, MPX, 舞台, 展览, 展台设计, 展台搭建, 品牌推广活动, 路演, 广告灯箱, 动态机械, 现场演唱会, 舞台机械, 舞台结构\";s:26:\"custom_zh_meta_description\";s:199:\"Melody Productionworx 专注于为全国各地的活动及现场演唱会提供舞台、展览展台、品牌推广活动、广告灯箱及动态机械解决方案的设计、施工与安装服务。\";s:17:\"custom_zh_meta_h1\";s:35:\"CÔNG TY TNHH MELODY PRODUCTIONWORX\";s:21:\"custom_zh_description\";s:190:\"Melody Productionworx专注于舞台、展位、路演活动(Activation)、广告灯箱以及活动与演唱会机械动感解决方案的设计、制作与安装,服务范围覆盖全国。\";s:17:\"custom_en_address\";s:50:\"B8/255E, Ap 2, Binh Hung Commune, Ho Chi Minh City\";s:14:\"custom_en_open\";s:30:\"Monday - Sunday: 08:00 - 18:00\";s:17:\"custom_zh_address\";s:62:\"B8/255E, 第2坊(Ấp 2), 平兴社(Bình Hưng), 胡志明市\";s:14:\"custom_zh_open\";s:29:\"周一至周日:08:00 - 18:00\";s:18:\"custom_link_tiktok\";s:37:\"https://www.tiktok.com/@mpxexhibition\";s:21:\"custom_link_pinterest\";s:16:\"https://mpx.vn/#\";s:20:\"custom_link_linkedIn\";s:63:\"https://www.linkedin.com/company/mpx-co-ltd/posts/?feedView=all\";}', 1, 1);
