--
-- Triggers `dc_comment`
--
DELIMITER $$
CREATE TRIGGER `trg_comment_delete` AFTER DELETE ON `dc_comment` FOR EACH ROW BEGIN
    UPDATE dc_products SET
        star = (
            SELECT COALESCE(ROUND(AVG(c.star), 1), 0)
            FROM dc_comment c
            WHERE c.pid = OLD.pid AND c.status = 1
        )
    WHERE id = OLD.pid;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_comment_delete_article` AFTER DELETE ON `dc_comment` FOR EACH ROW BEGIN
    UPDATE dc_articles SET
        star = (
            SELECT COALESCE(ROUND(AVG(c.star), 1), 0)
            FROM dc_comment c
            WHERE c.pid = OLD.pid AND c.status = 1
        )
    WHERE id = OLD.pid;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_comment_status_update` AFTER UPDATE ON `dc_comment` FOR EACH ROW BEGIN
    IF OLD.status != NEW.status THEN
        UPDATE dc_products SET
            star = (
                SELECT COALESCE(ROUND(AVG(c.star), 1), 0)
                FROM dc_comment c
                WHERE c.pid = NEW.pid AND c.status = 1
            )
        WHERE id = NEW.pid;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_comment_status_update_article` AFTER UPDATE ON `dc_comment` FOR EACH ROW BEGIN
    IF OLD.status != NEW.status THEN
        UPDATE dc_articles SET
            star = (
                SELECT COALESCE(ROUND(AVG(c.star), 1), 0)
                FROM dc_comment c
                WHERE c.pid = NEW.pid AND c.status = 1
            )
        WHERE id = NEW.pid;
    END IF;
END
$$
DELIMITER ;

